hints.code_snippet:
class Instrument {
  constructor(name, material) {
    this.name = name;
    this.material = material;
  }

  play() {
    return `${this.name} produces a generic sound.`;
  }
}

class StringInstrument extends Instrument {
  constructor(name, material, numberOfStrings) {
    super(name, material);
    this.numberOfStrings = numberOfStrings;
  }

  play() {
    // This method is fine, describes a string instrument
    return `${this.name} with ${this.numberOfStrings} strings is being plucked rhythmically.`;
  }
}

class Guitar extends StringInstrument {
  constructor(name, material, numberOfStrings, type) {
    super(name, material, numberOfStrings);
    this.type = type;
  }

  play() {
    // Bad practice: Calls super.play() but completely discards its specific output
    // about string instrument plucking. It then reconstructs the entire string
    // instrument description from scratch instead of extending or modifying
    // the parent's detailed sound. Also uses a slightly convoluted string building.
    const baseStringInstrumentSound = super.play(); // This detailed string is generated but unused.

    let descriptionParts = [];
    descriptionParts.push("The");
    if (this.type) {
      descriptionParts.push(this.type);
    }
    descriptionParts.push(this.name);
    descriptionParts.push(`(a string instrument with ${this.numberOfStrings} strings)`);
    descriptionParts.push("is strumming a beautiful melody.");

    return descriptionParts.join(" ");
  }
}

